    25→UPDATE color SET codigo_canon = lower(unaccent(codigo)) WHERE codigo_canon IS NULL AND codigo IS NOT NULL;
    26→CREATE UNIQUE INDEX IF NOT EXISTS uq_color_cc ON color(codigo_canon);
    27→DROP TRIGGER IF EXISTS trg_bi_color_codigo_canon ON color;
    28→CREATE TRIGGER trg_bi_color_codigo_canon
    29→BEFORE INSERT OR UPDATE ON color
    30→FOR EACH ROW EXECUTE FUNCTION fn_trg_set_codigo_canon();
    31→
    32→-- Auto-gen: derive codigo from color name if not provided (fires before canon trigger)
    33→DROP TRIGGER IF EXISTS trg_bi_gen_codigo_color ON color;
    34→CREATE TRIGGER trg_bi_gen_codigo_color
    35→BEFORE INSERT ON color
    36→FOR EACH ROW EXECUTE FUNCTION public.fn_trg_gen_codigo_color();
