    41→-- ── estado ─────────────────────────────────────────────────────
    42→ALTER TABLE estado
    43→    DROP COLUMN IF EXISTS estado_produccion,
    44→    DROP COLUMN IF EXISTS estado_comercial;
    45→ALTER TABLE estado
    46→    ADD COLUMN IF NOT EXISTS estado_produccion orden_produccion_estado_enum,
