    49→-- ═══════════════════════════════════════════════════════════════
    50→-- articulo_tipo (prod table: tipo_articulo) and articulo
    51→-- ─────────────────────────────────────────────────────────────
    52→-- These are the only catalog tables without a 'codigo' column in prod.
    53→-- Strategy: ALTER TABLE RENAME (atomic, preserves all FK constraints
    54→-- automatically — Postgres updates dependent tables/indexes on rename).
    55→-- We also add 'codigo' for consistency with every other catalog table.
    56→--
    57→-- After running, review backfilled codes for collisions/truncation before
    58→-- enforcing NOT NULL / UNIQUE on codigo (commented steps at the bottom).
    59→-- ═══════════════════════════════════════════════════════════════
    60→
    61→-- ── tipo_articulo → articulo_tipo ──────────────────────────────
    62→
    63→-- 1. Rename table (idempotent: skips if already renamed)
    64→DO $$ BEGIN
    65→    IF EXISTS (SELECT 1 FROM pg_tables WHERE schemaname = 'public' AND tablename = 'tipo_articulo') THEN
    66→        ALTER TABLE tipo_articulo RENAME TO articulo_tipo;
    67→    END IF;
    68→END $$;
    69→
    70→-- 2. Rename column tipo_articulo → nombre
    71→DO $$ BEGIN
    72→    IF EXISTS (
    73→        SELECT 1 FROM information_schema.columns
    74→        WHERE table_schema = 'public' AND table_name = 'articulo_tipo' AND column_name = 'tipo_articulo'
    75→    ) THEN
    76→        ALTER TABLE articulo_tipo RENAME COLUMN tipo_articulo TO nombre;
    77→    END IF;
    78→END $$;
    79→
    80→-- 3. Add codigo and backfill (UPPER + strip non-alphanum, same formula as color.codigo)
    81→ALTER TABLE articulo_tipo ADD COLUMN IF NOT EXISTS codigo TEXT;
    82→UPDATE articulo_tipo
    83→SET codigo = UPPER(regexp_replace(nombre, '[^a-zA-Z0-9]', '', 'g'))
    84→WHERE codigo IS NULL;
    85→
    86→-- 4. Add codigo_canon and backfill from codigo
    87→ALTER TABLE articulo_tipo ADD COLUMN IF NOT EXISTS codigo_canon TEXT;
    88→UPDATE articulo_tipo SET codigo_canon = lower(unaccent(codigo)) WHERE codigo_canon IS NULL AND codigo IS NOT NULL;
    89→CREATE UNIQUE INDEX IF NOT EXISTS uq_articulo_tipo_cc ON articulo_tipo(codigo_canon);
    90→
    91→-- 5. Attach standard trigger
    92→DROP TRIGGER IF EXISTS trg_bi_articulo_tipo_codigo_canon ON articulo_tipo;
    93→CREATE TRIGGER trg_bi_articulo_tipo_codigo_canon
    94→BEFORE INSERT OR UPDATE ON articulo_tipo
    95→FOR EACH ROW EXECUTE FUNCTION fn_trg_set_codigo_canon();
    96→
    97→-- REVIEW BEFORE ENFORCING:
    98→--   SELECT codigo, COUNT(*) FROM articulo_tipo GROUP BY codigo HAVING COUNT(*) > 1;
    99→-- Then enforce:
   100→--   ALTER TABLE articulo_tipo ALTER COLUMN codigo SET NOT NULL;
   101→--   ALTER TABLE articulo_tipo ADD CONSTRAINT articulo_tipo_codigo_uk UNIQUE (codigo);
   102→
   103→-- ── articulo ───────────────────────────────────────────────────
   104→
   105→-- 1. Rename articulo → nombre
   106→DO $$ BEGIN
   107→    IF EXISTS (
   108→        SELECT 1 FROM information_schema.columns
   109→        WHERE table_schema = 'public' AND table_name = 'articulo' AND column_name = 'articulo'
   110→    ) THEN
   111→        ALTER TABLE articulo RENAME COLUMN articulo TO nombre;
   112→    END IF;
   113→END $$;
   114→
   115→-- 2. Rename tipo_articulo_id → articulo_tipo_id
   116→DO $$ BEGIN
   117→    IF EXISTS (
   118→        SELECT 1 FROM information_schema.columns
   119→        WHERE table_schema = 'public' AND table_name = 'articulo' AND column_name = 'tipo_articulo_id'
   120→    ) THEN
   121→        ALTER TABLE articulo RENAME COLUMN tipo_articulo_id TO articulo_tipo_id;
   122→    END IF;
   123→END $$;
   124→
   125→-- 3. Add codigo and backfill
   126→ALTER TABLE articulo ADD COLUMN IF NOT EXISTS codigo TEXT;
   127→UPDATE articulo
   128→SET codigo = UPPER(regexp_replace(nombre, '[^a-zA-Z0-9]', '', 'g'))
   129→WHERE codigo IS NULL;
   130→
   131→-- 4. Add codigo_canon and backfill from codigo
   132→ALTER TABLE articulo ADD COLUMN IF NOT EXISTS codigo_canon TEXT;
   133→UPDATE articulo SET codigo_canon = lower(unaccent(codigo)) WHERE codigo_canon IS NULL AND codigo IS NOT NULL;
   134→CREATE UNIQUE INDEX IF NOT EXISTS uq_articulo_cc ON articulo(codigo_canon);
   135→
   136→-- 5. Add fibra and backfill from item_rollo_detalle
   137→--    MUST run before item_rollo_detalle.fibra is dropped (step below).
   138→--    Pre-check (run manually, must return 0 rows before proceeding):
   139→--      SELECT articulo_id, COUNT(DISTINCT fibra) n
   140→--      FROM item_rollo_detalle GROUP BY articulo_id HAVING COUNT(DISTINCT fibra) > 1;
   141→ALTER TABLE articulo ADD COLUMN IF NOT EXISTS fibra SMALLINT;
   142→
   143→UPDATE articulo ar
   144→SET fibra = CASE
   145→    WHEN ar.nombre ILIKE '%poly%' THEN 2
   146→    ELSE COALESCE(
   147→        (SELECT MAX(p.fibra)
   148→         FROM partida p
   149→         WHERE p.articulo_id = ar.id
   150→           AND p.fibra IS NOT NULL),
   151→        1   -- fallback if no partida data at all
   152→    )
   153→END
   154→WHERE ar.fibra IS NULL
   155→  AND ar.id IN (SELECT DISTINCT articulo_id FROM partida WHERE articulo_id IS NOT NULL);
   156→
   157→-- 6. Attach standard trigger
   158→DROP TRIGGER IF EXISTS trg_bi_articulo_codigo_canon ON articulo;
   159→CREATE TRIGGER trg_bi_articulo_codigo_canon
   160→BEFORE INSERT OR UPDATE ON articulo
   161→FOR EACH ROW EXECUTE FUNCTION fn_trg_set_codigo_canon();
   162→
   163→-- REVIEW BEFORE ENFORCING:
   164→--   SELECT codigo, COUNT(*) FROM articulo GROUP BY codigo HAVING COUNT(*) > 1;
   165→-- Then enforce:
   166→--   ALTER TABLE articulo ALTER COLUMN codigo SET NOT NULL;
   167→--   ALTER TABLE articulo ADD CONSTRAINT articulo_codigo_uk UNIQUE (codigo);
   168→
   169→-- ── item_rollo_detalle.fibra ────────────────────────────────────
   170→-- Drop fibra from item_rollo_detalle AFTER backfill above completes.
   171→ALTER TABLE IF EXISTS item_rollo_detalle DROP COLUMN IF EXISTS fibra;
   172→
   173→-- ── profiles → usuario ───────────────────────────────────────────
   174→-- Rename legacy Supabase profiles table and its columns to Spanish conventions.
   175→-- id (uuid, FK to auth.users) → auth_id
   176→-- id_usuario (integer, true PK) → id
   177→-- first_name → nombre, last_name → apellido
   178→DO $$ BEGIN
   179→    IF EXISTS (SELECT 1 FROM pg_tables WHERE schemaname = 'public' AND tablename = 'profiles') THEN
   180→        ALTER TABLE public.profiles RENAME TO usuario;
   181→    END IF;
   182→END $$;
   183→
   184→DO $$ BEGIN
   185→    IF EXISTS (SELECT 1 FROM information_schema.columns
   186→               WHERE table_schema = 'public' AND table_name = 'usuario' AND column_name = 'id') THEN
   187→        ALTER TABLE public.usuario RENAME COLUMN id TO auth_id;
   188→    END IF;
   189→END $$;
   190→
   191→DO $$ BEGIN
   192→    IF EXISTS (SELECT 1 FROM information_schema.columns
   193→               WHERE table_schema = 'public' AND table_name = 'usuario' AND column_name = 'id_usuario') THEN
   194→        ALTER TABLE public.usuario RENAME COLUMN id_usuario TO id;
   195→    END IF;
   196→END $$;
   197→
   198→DO $$ BEGIN
   199→    IF EXISTS (SELECT 1 FROM information_schema.columns
   200→               WHERE table_schema = 'public' AND table_name = 'usuario' AND column_name = 'first_name') THEN
   201→        ALTER TABLE public.usuario RENAME COLUMN first_name TO nombre;
   202→    END IF;
   203→END $$;
   204→
   205→DO $$ BEGIN
   206→    IF EXISTS (SELECT 1 FROM information_schema.columns
   207→               WHERE table_schema = 'public' AND table_name = 'usuario' AND column_name = 'last_name') THEN
   208→        ALTER TABLE public.usuario RENAME COLUMN last_name TO apellido;
   209→    END IF;
   210→END $$;
