     2→-- Step 3: Base trigger functions
     3→-- Must come before any table that uses these as triggers.
     4→-- ═══════════════════════════════════════════════════════════════
     5→
     6→-- Canonical code: lowercased, unaccented version of codigo
     7→-- Used by: item, unidad, item_tipo, insumo_tipo, colorante_tipo,
     8→--          inventario.almacen/ubicacion, mes.operacion/maquina/etc.
     9→-- NOTE: only attach to tables that have BOTH 'codigo' AND 'codigo_canon' columns.
    10→CREATE OR REPLACE FUNCTION public.fn_trg_set_codigo_canon()
    11→RETURNS trigger
    12→LANGUAGE plpgsql
    13→AS $$
    14→BEGIN
    15→    IF NEW.codigo IS NOT NULL THEN
    16→        NEW.codigo_canon := lower(unaccent(NEW.codigo));
    17→    END IF;
    18→    RETURN NEW;
    19→END;
    20→$$;
    21→
    22→-- ── User identity helper ──────────────────────────────────────────────────────
    23→-- Reads id_usuario from the JWT (injected at login by custom_access_token_hook).
    24→-- Zero DB cost. Requires hook registered: Supabase Dashboard →
    25→--   Authentication → Hooks → Custom Access Token → public.custom_access_token_hook
    26→CREATE OR REPLACE FUNCTION public.get_user_id()
    27→RETURNS int
    28→LANGUAGE sql
    29→STABLE
    30→SECURITY DEFINER
    31→SET search_path = public
    32→AS $$
    33→  SELECT (auth.jwt()->>'id_usuario')::int;
    34→$$;
    35→
    36→GRANT EXECUTE ON FUNCTION public.get_user_id TO authenticated, anon;
    37→
    38→-- Audit helpers
    39→CREATE OR REPLACE FUNCTION public.fn_trg_set_cre_fields()
    40→RETURNS trigger LANGUAGE plpgsql AS $$
    41→BEGIN
    42→    NEW.usr_cre := COALESCE(NEW.usr_cre, get_user_id());
    43→    NEW.fyh_cre := COALESCE(NEW.fyh_cre, now());
    44→    RETURN NEW;
    45→END;
    46→$$;
    47→
    48→CREATE OR REPLACE FUNCTION public.fn_trg_set_mod_fields()
    49→RETURNS trigger LANGUAGE plpgsql AS $$
    50→BEGIN
    51→    NEW.usr_cre := OLD.usr_cre;
    52→    NEW.fyh_cre := OLD.fyh_cre;
    53→    NEW.usr_mod := get_user_id();
    54→    NEW.fyh_mod := now();
    55→    RETURN NEW;
    56→END;
    57→$$;
    58→
    59→CREATE OR REPLACE FUNCTION public.fn_trg_set_elm_fields()
    60→RETURNS trigger LANGUAGE plpgsql AS $$
    61→BEGIN
    62→    IF OLD.flg_elm IS FALSE
    63→       AND NEW.flg_elm IS TRUE
    64→       AND OLD.fyh_elm IS NULL
    65→    THEN
    66→        NEW.usr_elm := get_user_id();
    67→        NEW.fyh_elm := now();
    68→    END IF;
    69→    RETURN NEW;
    70→END;
    71→$$;
    72→
    73→-- ── Code immutability ─────────────────────────────────────────────────────────
    74→-- Applied to every table with a codigo column. Codes are write-once: once set,
    75→-- they can never change. Rename = soft-delete old + create new.
    76→CREATE OR REPLACE FUNCTION public.fn_trg_immutable_codigo()
    77→RETURNS trigger LANGUAGE plpgsql AS $$
    78→BEGIN
    79→    IF OLD.codigo IS NOT NULL AND OLD.codigo IS DISTINCT FROM NEW.codigo THEN
    80→        RAISE EXCEPTION 'el codigo es inmutable en %. Desactive y cree un nuevo registro en su lugar.', TG_TABLE_NAME;
    81→    END IF;
    82→    RETURN NEW;
    83→END;
    84→$$;
    85→
    86→-- ── Hard-delete prevention ────────────────────────────────────────────────────
    87→-- Core business documents must never be hard-deleted — use flg_elm = true instead.
    88→CREATE OR REPLACE FUNCTION public.fn_trg_prevent_hard_delete()
    89→RETURNS trigger LANGUAGE plpgsql AS $$
    90→BEGIN
    91→    RAISE EXCEPTION 'el borrado no está permitido en %. Establezca flg_elm = true para borrar.', TG_TABLE_NAME;
    92→END;
    93→$$;
    94→
    95→-- ── Auto-gen: mes.maquina ─────────────────────────────────────────────────────
    96→-- Generates codigo = {maquina_tipo.codigo}-{NNN} scoped per tipo, if not provided.
    97→CREATE OR REPLACE FUNCTION mes.fn_trg_gen_codigo_maquina()
    98→RETURNS trigger LANGUAGE plpgsql AS $$
    99→DECLARE
   100→    v_tipo_codigo TEXT;
   101→    v_seq         INT;
   102→BEGIN
   103→    IF NEW.codigo IS NULL THEN
   104→        SELECT codigo INTO v_tipo_codigo FROM mes.maquina_tipo WHERE id = NEW.maquina_tipo_id;
   105→        SELECT COALESCE(MAX(
   106→            CASE WHEN codigo ~ ('^' || v_tipo_codigo || '-[0-9]+$')
   107→                 THEN (regexp_match(codigo, '[0-9]+$'))[1]::int
   108→                 ELSE 0 END
   109→        ), 0) + 1
   110→        INTO v_seq
   111→        FROM mes.maquina WHERE maquina_tipo_id = NEW.maquina_tipo_id;
   112→        NEW.codigo := v_tipo_codigo || '-' || LPAD(v_seq::text, 3, '0');
   113→    END IF;
   114→    RETURN NEW;
   115→END;
   116→$$;
   117→
   118→-- ── Auto-gen: inventario.ubicacion ───────────────────────────────────────────
   119→-- Generates codigo = {almacen_abbrev}-{NN} scoped per almacen, if not provided.
   120→-- Strips the 'ALM_' prefix from almacen.codigo to get the abbreviation.
   121→-- Convention: almacen codes are user-set with ALM_ prefix (e.g. ALM_INS, ALM_CRU).
   122→CREATE OR REPLACE FUNCTION inventario.fn_trg_gen_codigo_ubicacion()
   123→RETURNS trigger LANGUAGE plpgsql AS $$
   124→DECLARE
   125→    v_abbrev TEXT;
   126→    v_seq    INT;
   127→BEGIN
   128→    IF NEW.codigo IS NULL THEN
   129→        SELECT regexp_replace(codigo, '^ALM_', '') INTO v_abbrev
   130→        FROM inventario.almacen WHERE id = NEW.almacen_id;
   131→        SELECT COUNT(*) + 1 INTO v_seq
   132→        FROM inventario.ubicacion WHERE almacen_id = NEW.almacen_id;
   133→        NEW.codigo := v_abbrev || '-' || LPAD(v_seq::text, 2, '0');
   134→    END IF;
   135→    RETURN NEW;
   136→END;
   137→$$;
   138→
   139→-- ── Auto-gen: color ───────────────────────────────────────────────────────────
   140→-- Derives codigo by stripping non-alphanumeric from color name, uppercased.
   141→CREATE OR REPLACE FUNCTION public.fn_trg_gen_codigo_color()
   142→RETURNS trigger LANGUAGE plpgsql AS $$
   143→BEGIN
   144→    IF NEW.codigo IS NULL THEN
   145→        NEW.codigo := UPPER(regexp_replace(NEW.color, '[^a-zA-Z0-9]', '', 'g'));
   146→    END IF;
   147→    RETURN NEW;
   148→END;
   149→$$;
   150→
   151→-- ── Auto-gen: item (rollo) ────────────────────────────────────────────────────
   152→-- Fires AFTER INSERT on item_rollo_detalle, updates item.codigo when not yet set.
   153→-- Format: R-{articulo.codigo}-{fibra}-{C|T}  (R-RB-... for rib variants)
   154→CREATE OR REPLACE FUNCTION public.fn_trg_gen_codigo_item_rollo()
   155→RETURNS trigger LANGUAGE plpgsql AS $$
   156→DECLARE
   157→    v_articulo_codigo TEXT;
   158→    v_fibra           TEXT;
   159→    v_estado          TEXT;
   160→    v_rib             TEXT;
   161→BEGIN
   162→    SELECT codigo INTO v_articulo_codigo FROM articulo WHERE id = NEW.articulo_id;
   163→    SELECT COALESCE(fibra::text, '1') INTO v_fibra FROM articulo WHERE id = NEW.articulo_id;
   164→    v_estado := CASE WHEN NEW.flg_tenido THEN 'T' ELSE 'C' END;
   165→    v_rib    := CASE WHEN COALESCE(NEW.flg_rib, false) THEN 'RB-' ELSE '' END;
   166→    UPDATE item
   167→       SET codigo = UPPER('R-' || v_rib || v_articulo_codigo || '-' || v_fibra || '-' || v_estado)
   168→     WHERE id = NEW.item_id AND codigo IS NULL;
   169→    RETURN NEW;
   170→END;
   171→$$;
   172→
   173→-- ── Auto-gen: item (insumo) ───────────────────────────────────────────────────
   174→-- Fires AFTER INSERT on item_insumo_detalle, updates item.codigo when not yet set.
   175→-- Format: I-{QUIM|COL|AUX}-{DIR|DISP|RX?}-{NORMALIZED_NAME}
   176→CREATE OR REPLACE FUNCTION public.fn_trg_gen_codigo_item_insumo()
   177→RETURNS trigger LANGUAGE plpgsql AS $$
   178→DECLARE
   179→    v_it_codigo TEXT;
   180→    v_ct_codigo TEXT;
   181→    v_nombre    TEXT;
   182→    v_codigo    TEXT;
   183→BEGIN
   184→    SELECT it.codigo, ct.codigo, i.nombre
   185→      INTO v_it_codigo, v_ct_codigo, v_nombre
   186→      FROM item i
   187→      JOIN insumo_tipo it ON it.id = NEW.insumo_tipo_id
   188→      LEFT JOIN colorante_tipo ct ON ct.id = NEW.colorante_tipo_id
   189→     WHERE i.id = NEW.item_id;
   190→
   191→    v_codigo := 'I-' || v_it_codigo;
   192→    IF v_ct_codigo IS NOT NULL THEN
   193→        v_codigo := v_codigo || '-' || v_ct_codigo;
   194→    END IF;
   195→    v_codigo := v_codigo || '-' ||
   196→        trim(both '-' from
   197→            regexp_replace(
   198→                regexp_replace(UPPER(v_nombre) COLLATE "C", '\s+', ' ', 'g'),
   199→                '[^A-Z0-9]+', '-', 'g'));
   200→
   201→    UPDATE item SET codigo = v_codigo WHERE id = NEW.item_id AND codigo IS NULL;
   202→    RETURN NEW;
   203→END;
   204→$$;
   205→

