     8→-- =============================================================================
     9→-- SECTION 1: Custom Access Token Hook
    10→-- Fires on every login and token refresh.
    11→-- Injects user_permissions, user_roles, and id_usuario into the JWT.
    12→--
    13→-- After deploying: Supabase Dashboard → Authentication → Hooks
    14→--   → Custom Access Token → schema: public, function: custom_access_token_hook
    15→-- =============================================================================
    16→
    17→CREATE OR REPLACE FUNCTION public.custom_access_token_hook(event jsonb)
    18→RETURNS jsonb
    19→LANGUAGE plpgsql
    20→STABLE
    21→SECURITY DEFINER
    22→SET search_path = public, iam
    23→AS $$
    24→DECLARE
    25→  claims        jsonb;
    26→  v_numeric_id  integer;
    27→  v_permissions text[];
    28→  v_role_codes  text[];
    29→BEGIN
    30→  -- Bridge auth UUID → numeric id
    31→  SELECT id INTO v_numeric_id
    32→  FROM public.usuario
    33→  WHERE auth_id = (event->>'user_id')::uuid;
    34→
    35→  -- No usuario row = no permissions, id_usuario JWT claim stays NULL.
    36→  IF v_numeric_id IS NULL THEN
    37→    claims := event->'claims';
    38→    claims := jsonb_set(claims, '{user_permissions}', '[]'::jsonb);
    39→    claims := jsonb_set(claims, '{user_roles}',       '[]'::jsonb);
    40→    claims := jsonb_set(claims, '{id_usuario}',       'null'::jsonb);
    41→    RETURN jsonb_set(event, '{claims}', claims);
    42→  END IF;
    43→
    44→  -- Collect all permission codes across all roles
    45→  SELECT ARRAY_AGG(DISTINCT p.code) INTO v_permissions
    46→  FROM iam.user_rol ur
    47→  JOIN iam.rol_permiso rp ON rp.rol_id = ur.rol_id
    48→  JOIN iam.permiso p ON p.id = rp.permiso_id
    49→  WHERE ur.user_id = v_numeric_id;
    50→
    51→  -- Collect role codes
    52→  SELECT ARRAY_AGG(DISTINCT r.code) INTO v_role_codes
    53→  FROM iam.user_rol ur
    54→  JOIN iam.rol r ON r.id = ur.rol_id
    55→  WHERE ur.user_id = v_numeric_id;
    56→
    57→  claims := event->'claims';
    58→  claims := jsonb_set(claims, '{user_permissions}', COALESCE(to_jsonb(v_permissions), '[]'::jsonb));
    59→  claims := jsonb_set(claims, '{user_roles}',       COALESCE(to_jsonb(v_role_codes),  '[]'::jsonb));
    60→  claims := jsonb_set(claims, '{id_usuario}',       to_jsonb(v_numeric_id));
    61→
    62→  RETURN jsonb_set(event, '{claims}', claims);
    63→END;
    64→$$;
    65→
    66→GRANT EXECUTE ON FUNCTION public.custom_access_token_hook TO supabase_auth_admin;
    67→REVOKE EXECUTE ON FUNCTION public.custom_access_token_hook FROM PUBLIC, authenticated, anon;
    68→
    69→
    70→-- =============================================================================
    71→-- SECTION 2: RLS Helper
    72→-- STABLE = result cached per query, not per row. Safe and efficient for RLS.
