    59→-- doc.factura: only block hard-delete once emitted or annulled.
    60→-- Borradores (drafts) may be hard-deleted freely.
    61→CREATE OR REPLACE FUNCTION doc.fn_trg_factura_prevent_hard_delete()
    62→RETURNS TRIGGER LANGUAGE plpgsql AS $$
    63→BEGIN
    64→    IF OLD.estado IN ('emitida', 'anulada') THEN
    65→        RAISE EXCEPTION
    66→            'Factura id=% (%) no puede eliminarse: es un documento tributario emitido. Use una Nota de Crédito para anularla.',
    67→            OLD.id, OLD.estado
    68→            USING ERRCODE = 'restrict_violation';
    69→    END IF;
    70→    RETURN OLD;
    71→END;
    72→$$;
