    79→-- ── Audit schema ──────────────────────────────────────────────────────────────
    80→CREATE SCHEMA IF NOT EXISTS audit;
    81→CREATE TABLE IF NOT EXISTS audit.data_audit (
    82→    audit_id      bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    83→    schema_name   TEXT NOT NULL,
    84→    table_name    TEXT NOT NULL,
    85→    row_id        bigint NOT NULL,
    86→    operacion     TEXT NOT NULL CHECK (operacion IN ('INSERT','UPDATE','DELETE')),
    87→    old_data      JSONB,
    88→    new_data      JSONB,
    89→    usr_id        int,
    90→    fyh_evento    TIMESTAMPTZ NOT NULL DEFAULT now()
    91→);
    92→
    93→-- ── Audit row function ────────────────────────────────────────────────────────
    94→-- fn_trg_set_cre/mod/elm_fields are defined in step 3 (not repeated here).
    95→CREATE OR REPLACE FUNCTION audit.fn_audit_row()
    96→RETURNS TRIGGER
    97→LANGUAGE plpgsql
    98→SECURITY DEFINER
    99→SET search_path = audit, public
   100→AS $$
   101→DECLARE
   102→    v_id bigint;
   103→BEGIN
   104→    IF TG_TABLE_SCHEMA = 'audit' THEN
   105→        RETURN COALESCE(NEW, OLD);
   106→    END IF;
   107→    v_id := COALESCE(NEW.id, OLD.id);
   108→    INSERT INTO audit.data_audit (
   109→        schema_name, table_name, row_id, operacion, old_data, new_data, usr_id
   110→    )
   111→    VALUES (
   112→        TG_TABLE_SCHEMA,
   113→        TG_TABLE_NAME,
   114→        v_id,
   115→        TG_OP,
   116→        CASE WHEN TG_OP IN ('UPDATE','DELETE') THEN to_jsonb(OLD) END,
   117→        CASE WHEN TG_OP IN ('INSERT','UPDATE') THEN to_jsonb(NEW) END,
   118→        get_user_id()
   119→    );
   120→    RETURN COALESCE(NEW, OLD);
   121→END;
   122→$$;
