   124→-- ── Lote sequence trigger ─────────────────────────────────────────────────────
   125→CREATE OR REPLACE FUNCTION inventario.trfn_generar_secuencia_lote()
   126→RETURNS trigger LANGUAGE plpgsql AS $$
   127→DECLARE
   128→    v_ano INT;
   129→BEGIN
   130→    v_ano := date_part('year', COALESCE(NEW.fyh_cre, NOW()));
   131→    INSERT INTO inventario.lote_secuencia_anual (ano, ultimo_valor)
   132→    VALUES (v_ano, 1)
   133→    ON CONFLICT (ano)
   134→    DO UPDATE SET ultimo_valor = inventario.lote_secuencia_anual.ultimo_valor + 1
   135→    RETURNING ultimo_valor INTO NEW.secuencia;
   136→    RETURN NEW;
   137→END;
   138→$$;
   139→
   140→CREATE TRIGGER trg_bi_lote_secuencia
   141→BEFORE INSERT ON inventario.lote
   142→FOR EACH ROW
   143→WHEN (NEW.secuencia IS NULL)
   144→EXECUTE FUNCTION inventario.trfn_generar_secuencia_lote();
