CREATE OR REPLACE FUNCTION doc.crear_partida(p_partida jsonb)
 RETURNS text
LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'iam', 'notification', 'public','doc','mes'
AS $function$
DECLARE
    v_message   text;
    v_detail    text;
    v_hint      text;
    v_context   text;
    v_sqlstate  text;
    v_partida_id   INT;
    v_tipo_codigo text;
    v_usr_id int := get_user_id();

BEGIN
 INSERT INTO logs_api(function_name, user_id, params)
        VALUES ('crear_partida', v_usr_id, p_partida);

-------------------------------------------------------------------------
    INSERT INTO doc.partida (prioridad_id,tercero_id,tenido_id,malla,rendimiento,ancho,color_x_cliente_id,flg_antipilling,fecha_acordada)
    VALUES (
       ( p_partida->>'prioridad_id')::INT,
