-- Prevent editing a recipe that has already been executed.
CREATE OR REPLACE FUNCTION receta.fn_trg_lavado_maquina_immutable()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM mes.lavado_maquina
        WHERE receta_id = OLD.id AND estado = 'COMPLETADO'
    ) THEN
        RAISE EXCEPTION
            'receta.lavado_maquina id=% cannot be modified: it has completed executions',
            OLD.id;
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_bu_lavado_maquina_immutable
BEFORE UPDATE ON receta.lavado_maquina
FOR EACH ROW EXECUTE FUNCTION receta.fn_trg_lavado_maquina_immutable();

-- ── receta.lavado_maquina_paso ────────────────────────────────
CREATE TABLE receta.lavado_maquina_paso (
    id           INT      GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    receta_id    INT      NOT NULL REFERENCES receta.lavado_maquina(id),
    operacion_id SMALLINT NOT NULL REFERENCES receta.operacion(id),
    orden        SMALLINT NOT NULL,
    ph           NUMERIC(4,2),
    temperatura  NUMERIC(5,2),
    tiempo_min   SMALLINT,
    nota         TEXT,
    UNIQUE(receta_id, orden)
);

-- ── receta.lavado_maquina_paso_insumo ─────────────────────────
CREATE TABLE receta.lavado_maquina_paso_insumo (
    id       INT           GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    paso_id  INT           NOT NULL REFERENCES receta.lavado_maquina_paso(id) ON DELETE CASCADE,
    item_id  INT           NOT NULL REFERENCES item(id),
    cantidad NUMERIC(8,4)  NOT NULL,
    orden    SMALLINT      NOT NULL,
    UNIQUE(paso_id, orden)
);

-- ── Grants ────────────────────────────────────────────────────
